const loader=document.querySelector('#loader');setTimeout(()=>loader.classList.add('done'),3000);
document.querySelector('#replay').addEventListener('click',()=>{loader.classList.remove('done');loader.style.animation='none';void loader.offsetWidth;loader.style.animation='';setTimeout(()=>loader.classList.add('done'),3000)});
document.querySelector('#year').textContent=new Date().getFullYear();
const observer=new IntersectionObserver(items=>items.forEach(item=>{if(item.isIntersecting){item.target.classList.add('visible');observer.unobserve(item.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'});
const visual=document.querySelector('#hero-visual');if(visual&&matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){visual.addEventListener('mousemove',e=>{const r=visual.getBoundingClientRect();visual.style.transform=`rotateY(${(e.clientX-r.left-r.width/2)/50}deg) rotateX(${-(e.clientY-r.top-r.height/2)/70}deg)`});visual.addEventListener('mouseleave',()=>visual.style.transform='')}
const booking=document.querySelector('#booking'),form=document.querySelector('#booking-form'),result=document.querySelector('#booking-result'),select=document.querySelector('#treatment-select');function openBooking(treatment){if(treatment)select.value=treatment;form.hidden=false;result.hidden=true;booking.showModal()}document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking());document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const today=new Date();document.querySelector('#date').min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');form.onsubmit=e=>{e.preventDefault();const d=new FormData(form);document.querySelector('#summary').textContent=`${d.get('name').trim()}, your selected care is ${d.get('treatment').toLowerCase()} on ${new Date(d.get('date')+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}, ${d.get('time').toLowerCase()}.`;form.hidden=true;result.hidden=false};document.querySelector('#edit-request').onclick=()=>{form.hidden=false;result.hidden=true};
const treatmentData={'Preventive dentistry':['Everyday smile care','Build a strong foundation for your oral health with care focused on prevention.',['Dental examinations and oral health reviews','Professional cleaning and hygiene guidance','Advice tailored to your daily routine']],'Cosmetic dentistry':['A little more confidence','Explore ways to refresh your smile while respecting what makes it uniquely yours.',['Whitening suitability consultation','Veneer and cosmetic bonding discussions','A personalised plan based on your smile goals']],'Clear aligners':['Your smile, in balance','Understand your alignment options with an assessment of your teeth and bite.',['Orthodontic assessment','Discussion of aligners and suitable alternatives','Guidance on treatment commitment and follow-up']],'Restorative dentistry':['Restore the everyday','Explore treatment options for damaged or missing teeth and comfortable everyday function.',['Fillings and crown assessments','Bridge and implant consultations','A plan that considers your long-term oral health']]};const td=document.querySelector('#treatment-dialog');let activeTreatment='';document.querySelectorAll('[data-treatment]').forEach(b=>b.onclick=()=>{activeTreatment=b.dataset.treatment;const data=treatmentData[activeTreatment];document.querySelector('#detail-title').textContent=data[0];document.querySelector('#detail-copy').textContent=data[1];document.querySelector('#detail-list').replaceChildren(...data[2].map(s=>{const li=document.createElement('li');li.textContent=s;return li}));td.showModal()});document.querySelector('#detail-book').onclick=()=>{td.close();openBooking(activeTreatment)};
